"""Validate and package one immutable 32-pose skeletal render sequence."""
from pathlib import Path
from PIL import Image
import hashlib,json,sys,numpy as np
R=Path(__file__).resolve().parents[1];source=R/'work/hand-rig/frames';out=R/'public/assets/hand-sequence';out.mkdir(parents=True,exist_ok=True)
frames=[];hashes=[];areas=[];differences=[];previous=None
for index in range(32):
 p=source/f'hand-{index:03}.png';im=Image.open(p).convert('RGBA');assert im.size==(720,960),str(p);array=np.asarray(im);alpha=array[:,:,3];assert alpha.min()==0 and alpha.max()==255;assert np.any(alpha[-1,:]>0),f'Wrist no longer reaches frame bottom at {index}'
 dest=out/f'hand-{index:03}.webp';im.save(dest,'WEBP',quality=94,method=6,alpha_quality=100,exact=True);decoded=Image.open(dest).convert('RGBA');assert decoded.size==im.size;assert np.array_equal(np.asarray(decoded)[:,:,3],alpha),'WebP altered alpha'
 digest=hashlib.sha256(p.read_bytes()).hexdigest();hashes.append(digest);area=int((alpha>127).sum());areas.append(area)
 if previous is not None:differences.append(float(np.abs(array.astype(float)-previous.astype(float)).mean()))
 previous=array
 url=f'./assets/hand-sequence/{dest.name}';frames.append({'src':url,'foreground':url,'progress':index/31,'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'bytes':dest.stat().st_size,'alphaPixels':area})
assert len(set(hashes))==32,'Every anatomical pose must be independently rendered and distinct'
assert min(differences)>0,'Adjacent frames must move'
license=(R/'work/hand-rig/source/ASSETS-LICENSE-MIT.md').read_text();(out/'LICENSE.txt').write_text(license+'\nAsset source: https://github.com/immersive-web/webxr-input-profiles/tree/main/packages/assets/profiles/generic-hand\nModified with connected forearm extension, reflected presentation, continuous anatomical articulation, and procedural/UV skin materials.\n')
state=json.loads((R/'reports/hand-rig/render-state.json').read_text());meta=json.loads((R/'public/assets/renders/handheld-card.metadata.json').read_text());manifest={'version':1,'frames':frames,'width':720,'height':960,'dimensions':[720,960],'frameCount':32,'startPose':'camera-facing palm with fingers nearly together','endPose':'camera-facing planar finger fan, hand slightly lower','motion':'same weighted 25-joint mesh, fixed camera, reversible absolute pose index','rootMotion':{'coordinateSystem':'Blender meters','translationFrom':[0,0,0],'translationTo':state['rootDisplacement'],'interpolation':'linear by handOpen','rotationXDegreesFrom':0,'rotationXDegreesTo':0,'poseVariant':'FRONT','rootDropMeters':state['rootDropMeters']},'camera':meta['camera'],'contact':{'normalized':[.5,.73],'description':'Frontal fingers visibly overlap the lower card on screen while opening and lowering; model-space separation is positive and is not a physical grasp.'},'layers':{'src':'full hand, below independent card','foreground':'identical full hand, above card until release','sameImageReason':'Independently verified all 32 poses have positive front-of-card clearance; no card holdout or skin cutout needed.'},'source':{'url':'https://github.com/immersive-web/webxr-input-profiles/blob/main/packages/assets/profiles/generic-hand/right.glb','sha256':'291790c14f7f88a7f9bd35330c47392ed8e8d395ae6728f4bb7089f1bc1f2b96','license':'MIT, copyright 2019 Amazon'},'geometry':{'sourceSkinCount':1,'weightedJointCount':25,'sourceVertexCount':1360,'sourceTriangleCount':2314,'fingerCount':5,'changes':['connected wrist extension','mirrored presentation','two-level subdivision','positional seam welding and smooth recomputed normals','dual-quaternion preserve-volume skinning'],'independentGeneratedPoses':False},'clearanceScope':'Software checks describe the frozen source 3D scene before CSS presentation transforms; they do not prove zero-gap physical contact or browser-space collision.','poseVariant':'FRONT','poseSpecification':json.loads((R/'reports/hand-rig/render-state.json').read_text())['poseSpecification'],'render_script_sha256':hashlib.sha256((R/'scripts/render-hand-sequence.py').read_bytes()).hexdigest(),'textureProjection':{'stableUv':'CameraSkin','preservedFromPriorRig':True,'projectionRegistrationSha256':state['stableUvSourceSha256'],'wristBoundaryBlend':'fixed rest-UV fade over v=0..0.10','appearance':'AI-created shape-preserving palmar surface detail, affine-aligned and used as bounded linear-light albedo detail; no generated per-pose hands','alignmentIoU':.95431,'alignmentIoUScope':'prior source texture and accepted original projection, preserved through exact UV reuse'},'render':{'renderer':'Blender 4.3.2 Cycles CPU','alpha':True,'samples':state['samples'],'sameSeed':True,'viewTransform':'AgX'},'palmAlignment':{'normal':state['palmNormal'],'cameraAxisNormal':state['cameraFacingNormal'],'angleDegrees':state['palmAngleDegrees'],'lockedThroughoutOpening':True},'reverse':'The same decoded frames are indexed in reverse; no transition or alternate images.'}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
report={'frames':32,'uniquePoseHashes':len(set(hashes)),'dimensions':[720,960],'alphaLossless':True,'totalBytes':sum(f['bytes'] for f in frames),'alphaAreaMinMax':[min(areas),max(areas)],'adjacentMeanAbsoluteRgbaDifferences':differences,'sourceRenderHashes':hashes,'firstLastDifferent':hashes[0]!=hashes[-1]};(R/'reports/hand-rig/sequence-validation.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
